const r = await tools.exec_command({cmd:"cd /app && python - <<'PY'
import json,numpy as np
from scipy.optimize import minimize_scalar
from model import _occupation
p=json.load(open('data/calibration.json'))
y=np.array([r['value'] for r in p]); sig=np.array([r['sigma'] for r in p])
def obj(s):
 return np.sum(((np.array([_occupation(r['input']['orbital_energy'],r['input']['temperature'],s*r['input']['contact_multiplier']) for r in p])-y)/sig)**2)
r=minimize_scalar(obj,bounds=(.65,.95),method='bounded',options={'xatol':1e-13})
print(r.x,r.fun,r)
# grouped means and expected at fit
from collections import defaultdict
g=defaultdict(list)
for x in p:g[(x['input']['orbital_energy'],x['input']['temperature'])].append(x['value'])
for k,v in g.items(): print(k,np.mean(v),np.std(v,ddof=1),_occupation(*k,r.x))
PY","workdir":"/app","yield_time_ms":10000,"max_output_tokens":20000});
text(r.output);

const r = await tools.exec_command({cmd:"cd /app && python - <<'PY'
import numpy as np
from model import Model
m=Model()
rows=[]
for e in np.linspace(0,.8,9):
 for t in np.linspace(.2,.8,7):
  for c in [1,3,4]:
   rows.append({'orbital_energy':float(e),'temperature':float(t),'contact_multiplier':c})
a=m.predict(rows)
print(a.min(),a.max(),np.isfinite(a).all(),a.shape)
print('bad',[(rows[i],a[i]) for i in range(len(a)) if not (0<=a[i]<=1)])
PY","workdir":"/app","yield_time_ms":10000,"max_output_tokens":10000});
